// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(c), 20 ether);

        // First call: set pastBlockTime (reference works, mutant reverts because pastBlockTime==0 fails)
        vm.warp(10);
        vm.prank(address(0x01));
        (bool ok1,) = address(c).call{value: 10 ether}("");

        // Second call at a block where block.number % 15 == 0, timestamp > pastBlockTime
        vm.roll(15);
        vm.warp(20);
        uint balanceBefore = address(c).balance;
        vm.prank(address(0x02));
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // For the reference: pastBlockTime != 0 after first call, so second call succeeds and sends Ether
        // For the mutant: first call reverts (pastBlockTime==0 fails), so pastBlockTime remains 0, second call also reverts (requires pastBlockTime==0 fails because block.timestamp>0)
        // So the observable divergence: reference's second call succeeds (ok2==true), mutant reverts (ok2==false).
        assertTrue(ok2 == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.number to a multiple of 15 so that the transfer happens
        vm.roll(15);
        // Set block.timestamp to 10 (must be > pastBlockTime which is 0 initially)
        vm.warp(10);
        // Fund caller
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);

        // First fallback call — will succeed on reference, revert on buggy
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // Check balances: reference contract has 0 balance (transferred out), buggy has 10 ether
        uint contractBal = address(c).balance;

        // The reference passes: success is true and contractBal is 0
        // The bug fails: success is false and contractBal is 10 ether
        // We assert that the call succeeded, which the reference does and the bug does not
        assertTrue(success && contractBal == 0);
    }
}
